package com.keyforge.nativeload;
import com.keyforge.iiq.config.SchemaName;import com.keyforge.iiq.parquet.ParquetIds;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.util.*;
public final class NativeWorkgroupMembershipRepository {private final String schema,table;public enum Outcome{INSERTED,UPDATED}public NativeWorkgroupMembershipRepository(String s){schema=SchemaName.validate(s);table=schema+".kf_workgroup_member";}public String targetTable(){return table;}public void ensure(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.execute("CREATE SCHEMA IF NOT EXISTS "+schema);s.execute("CREATE TABLE IF NOT EXISTS "+table+" (id uuid PRIMARY KEY,workgroup_id uuid,identity_id uuid,member_name text,first_name text,last_name text,member_is_workgroup boolean,src_system text,src_interface text,src_object_type text,src_object_id text,src_natural_key text,extraction_run_id text,record_hash text,is_deleted boolean NOT NULL DEFAULT false,deleted_at timestamptz,extracted_at timestamptz NOT NULL DEFAULT now())");for(String x:List.of("member_is_workgroup boolean","src_system text","src_interface text","src_object_type text","src_object_id text","src_natural_key text","extraction_run_id text","record_hash text","is_deleted boolean NOT NULL DEFAULT false","deleted_at timestamptz"))s.execute("ALTER TABLE "+table+" ADD COLUMN IF NOT EXISTS "+x);}}static String uuid(String id){String x=ParquetIds.canonicalUuid(id);if(x==null)throw new NativeImportException("Native identity/workgroup ID is not UUID-shaped: "+id);return x;}static String edgeId(NativeWorkgroupMembershipRecord r){return ParquetIds.deterministicUuid("native-workgroup-member|"+uuid(r.workgroupId)+"|"+uuid(r.identityId));}static String hash(NativeWorkgroupMembershipRecord r){String v=String.join("|",Objects.toString(r.workgroupId,""),Objects.toString(r.identityId,""),Objects.toString(r.workgroupName,""),Objects.toString(r.identityName,""),Objects.toString(r.firstName,""),Objects.toString(r.lastName,""),Objects.toString(r.memberIsWorkgroup,""));try{byte[]d=MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format("%02x",x&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}public Outcome upsert(Connection c,NativeWorkgroupMembershipRecord r)throws SQLException{String q="INSERT INTO "+table+"(id,workgroup_id,identity_id,member_name,first_name,last_name,member_is_workgroup,src_system,src_interface,src_object_type,src_object_id,src_natural_key,extraction_run_id,record_hash,is_deleted,deleted_at) VALUES(?::uuid,?::uuid,?::uuid,?,?,?,?,?,?,?,?,?,?,?,false,null) ON CONFLICT(id) DO UPDATE SET workgroup_id=excluded.workgroup_id,identity_id=excluded.identity_id,member_name=excluded.member_name,first_name=excluded.first_name,last_name=excluded.last_name,member_is_workgroup=excluded.member_is_workgroup,src_system=excluded.src_system,src_interface=excluded.src_interface,src_object_type=excluded.src_object_type,src_object_id=excluded.src_object_id,src_natural_key=excluded.src_natural_key,extraction_run_id=excluded.extraction_run_id,record_hash=excluded.record_hash,is_deleted=false,deleted_at=null,extracted_at=now() RETURNING(xmax=0)";try(PreparedStatement p=c.prepareStatement(q)){int i=1;p.setString(i++,edgeId(r));p.setString(i++,uuid(r.workgroupId));p.setString(i++,uuid(r.identityId));p.setString(i++,r.identityName);p.setString(i++,r.firstName);p.setString(i++,r.lastName);if(r.memberIsWorkgroup==null)p.setNull(i++,Types.BOOLEAN);else p.setBoolean(i++,r.memberIsWorkgroup);p.setString(i++,r.srcSystem);p.setString(i++,"native_iiq_java_api");p.setString(i++,"sailpoint.object.Identity.workgroups");p.setString(i++,r.identityId);p.setString(i++,r.workgroupId+"|"+r.identityId);p.setString(i++,r.runId);p.setString(i,hash(r));try(ResultSet rs=p.executeQuery()){return rs.next()&&rs.getBoolean(1)?Outcome.INSERTED:Outcome.UPDATED;}}}public int sweep(Connection c,Collection<String>ids)throws SQLException{if(ids.isEmpty())return 0;String q="UPDATE "+table+" SET is_deleted=true,deleted_at=now() WHERE is_deleted=false AND id NOT IN ("+String.join(",",Collections.nCopies(ids.size(),"?::uuid"))+")";try(PreparedStatement p=c.prepareStatement(q)){int i=1;for(String id:ids)p.setString(i++,id);return p.executeUpdate();}}}
